INSERT INTO public.prompts (id, title, type, category, question_text, chart_description, illustration_type, min_word_count, recommended_time_minutes)
VALUES
  ('task2-001-online-degrees-vs-traditional-un', 'Online Degrees vs Traditional University', 'TASK_2_ESSAY', 'Education & Higher Learning (Agree / Disagree)', 'Some people believe that online university degrees will soon completely replace traditional on-campus education. To what extent do you agree or disagree with this prediction?', null, null, 250, 40),
  ('task2-002-free-higher-education-funded-by-', 'Free Higher Education Funded by Governments', 'TASK_2_ESSAY', 'Education & Higher Learning (Discuss Both Views & Opinion)', 'Some people think that university education should be completely free for all qualified students, paid for by the government. Others argue that students should fund their own higher education as it primarily benefits their individual careers. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-003-practical-job-skills-vs-theoreti', 'Practical Job Skills vs Theoretical Academics', 'TASK_2_ESSAY', 'Education & Higher Learning (Discuss Both Views & Opinion)', 'Some educators believe that schools and colleges should focus primarily on teaching practical vocational skills needed for employment. Others think education should prioritize theoretical knowledge and broad intellectual disciplines. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-004-single-sex-vs-co-educational-sch', 'Single-Sex vs Co-Educational Schools', 'TASK_2_ESSAY', 'Education & Higher Learning (Advantages vs Disadvantages)', 'In some countries, many parents choose to send their children to single-sex schools. Do the advantages of single-sex education outweigh the disadvantages?', null, null, 250, 40),
  ('task2-005-mandatory-physical-education-in-', 'Mandatory Physical Education in Curricula', 'TASK_2_ESSAY', 'Education & Higher Learning (Agree / Disagree)', 'All primary and secondary schools should make physical education and sport compulsory every school day until graduation. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-006-school-homework-quantity-for-chi', 'School Homework Quantity for Children', 'TASK_2_ESSAY', 'Education & Higher Learning (Discuss Both Views & Opinion)', 'Some people argue that daily homework puts unnecessary stress on young children and should be banned. Others believe homework is essential for reinforcing classroom learning and developing self-discipline. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-007-foreign-language-learning-in-ear', 'Foreign Language Learning in Early Childhood', 'TASK_2_ESSAY', 'Education & Higher Learning (To What Extent)', 'Some experts recommend that children should begin learning a foreign language in primary school rather than secondary school. Do the advantages of early foreign language acquisition outweigh its drawbacks?', null, null, 250, 40),
  ('task2-008-financial-literacy-personal-fina', 'Financial Literacy & Personal Finance Education', 'TASK_2_ESSAY', 'Education & Higher Learning (Agree / Disagree)', 'Schools should teach children how to manage money, budget, and invest as a compulsory subject alongside mathematics and science. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-009-teacher-performance-linked-to-st', 'Teacher Performance Linked to Student Exam Results', 'TASK_2_ESSAY', 'Education & Higher Learning (Advantages vs Disadvantages)', 'Some countries propose evaluating teachers and determining their salary bonuses based on their students'' standardized examination scores. Do the advantages of this policy outweigh the disadvantages?', null, null, 250, 40),
  ('task2-010-arts-music-and-drama-in-school-c', 'Arts, Music and Drama in School Curricula', 'TASK_2_ESSAY', 'Education & Higher Learning (Agree / Disagree)', 'Subjects like art, music, and drama are often considered less important than science, technology, and math (STEM). Some argue arts education is a waste of school resources. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-011-streaming-by-ability-vs-mixed-ab', 'Streaming by Ability vs Mixed-Ability Classes', 'TASK_2_ESSAY', 'Education & Higher Learning (Discuss Both Views & Opinion)', 'Some educational institutions group students into classrooms based on their academic ability, while others believe students of all abilities should study together. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-012-gap-year-before-university', 'Gap Year Before University', 'TASK_2_ESSAY', 'Education & Higher Learning (Advantages vs Disadvantages)', 'An increasing number of secondary school graduates take a gap year to work or travel before starting university. Do the advantages of taking a gap year outweigh the disadvantages?', null, null, 250, 40),
  ('task2-013-parental-responsibility-for-scho', 'Parental Responsibility for School Discipline', 'TASK_2_ESSAY', 'Education & Higher Learning (Two-Part Question)', 'In many countries, discipline problems and student misconduct in classrooms are rising. What are the main causes of this problem, and who should take the primary responsibility for resolving it: parents or teachers?', null, null, 250, 40),
  ('task2-014-standardized-examinations-vs-con', 'Standardized Examinations vs Continuous Assessment', 'TASK_2_ESSAY', 'Education & Higher Learning (Discuss Both Views & Opinion)', 'Some educators believe formal final examinations are the most equitable way to assess student knowledge. Others argue continuous assessment through coursework and projects gives a fairer reflection of ability. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-015-university-quotas-for-underrepre', 'University Quotas for Underrepresented Groups', 'TASK_2_ESSAY', 'Education & Higher Learning (Agree / Disagree)', 'Universities should accept equal numbers of male and female students in every subject, regardless of individual application test scores. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-016-artificial-intelligence-mass-une', 'Artificial Intelligence & Mass Unemployment', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Discuss Both Views & Opinion)', 'Some economists predict that generative AI and robotics will eliminate millions of professional jobs, causing catastrophic unemployment. Others believe AI will create brand new industries and elevate human productivity. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-017-social-media-impact-on-human-int', 'Social Media Impact on Human Interaction', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Discuss Both Views & Opinion)', 'Social networking websites have allowed people to connect globally like never before. However, critics argue these platforms make people more isolated and anti-social in real life. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-018-children-and-smartphone-screen-t', 'Children and Smartphone Screen Time', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Causes & Solutions)', 'Young children are spending an unprecedented number of hours per day staring at smartphone and tablet screens. What are the primary reasons for this trend, and what measures can parents and governments adopt to minimize its harmful effects?', null, null, 250, 40),
  ('task2-019-automated-surveillance-public-pr', 'Automated Surveillance & Public Privacy', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Agree / Disagree)', 'The widespread installation of public CCTV cameras and facial recognition technology reduces crime significantly, making the loss of personal privacy fully justified. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-020-cashless-societies-digital-payme', 'Cashless Societies & Digital Payments', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Advantages vs Disadvantages)', 'Many nations are moving towards a completely cashless economy where all financial transactions occur digitally. Do the advantages of a cashless society outweigh the disadvantages?', null, null, 250, 40),
  ('task2-021-autonomous-vehicles-self-driving', 'Autonomous Vehicles & Self-Driving Cars', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Advantages vs Disadvantages)', 'In the near future, driverless cars are expected to dominate urban roads. Do the advantages of autonomous transport outweigh the potential safety and ethical disadvantages?', null, null, 250, 40),
  ('task2-022-printed-books-and-libraries-vs-e', 'Printed Books and Libraries vs E-Books', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (To What Extent)', 'With the rise of internet search engines and e-books, public libraries and paper books have become obsolete and represent an unnecessary public expenditure. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-023-cyberbullying-and-internet-anony', 'Cyberbullying and Internet Anonymity', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Problem & Solution)', 'Online harassment and cyberbullying have become pervasive problems worldwide. What are the factors contributing to cyberbullying, and should internet users be required to register with real legal identities to prevent it?', null, null, 250, 40),
  ('task2-024-robotic-automation-in-elderly-he', 'Robotic Automation in Elderly Healthcare', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Advantages vs Disadvantages)', 'As populations age, some healthcare systems are deploying companion robots and automated machines to care for elderly citizens. Do the advantages of robotic caregiving outweigh its drawbacks?', null, null, 250, 40),
  ('task2-025-video-games-and-youth-violence', 'Video Games and Youth Violence', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Discuss Both Views & Opinion)', 'Some psychologists claim that playing violent video games promotes aggressive antisocial behavior in adolescents. Others believe video games are harmless entertainment that sharpens strategic reflexes. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-026-personal-data-collection-by-tech', 'Personal Data Collection by Tech Monopolies', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Agree / Disagree)', 'Large technology corporations collect massive volumes of personal data from users in exchange for free digital services. Governments should heavily regulate or prohibit this practice. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-027-space-colonization-vs-earth-sust', 'Space Colonization vs Earth Sustainability', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Agree / Disagree)', 'Billions of dollars are spent attempting to explore and colonize Mars and outer space. Some argue that all space funding should be redirected towards addressing climate change and poverty on Earth. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-028-telemedicine-remote-medical-cons', 'Telemedicine & Remote Medical Consultations', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Advantages vs Disadvantages)', 'Many patients now consult doctors through digital video apps rather than visiting a clinic in person. Do the advantages of virtual telemedicine outweigh its disadvantages?', null, null, 250, 40),
  ('task2-029-impact-of-digital-automation-on-', 'Impact of Digital Automation on Traditional Crafts', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Two-Part Question)', 'Modern mass production and automated 3D manufacturing are causing traditional handcrafts and artisan trades to disappear. Why is this happening, and is it important to preserve traditional handcrafted production?', null, null, 250, 40),
  ('task2-030-the-right-to-disconnect-from-wor', 'The Right to Disconnect from Work Communication', 'TASK_2_ESSAY', 'Technology, AI & Digital Life (Agree / Disagree)', 'Due to smartphones and emails, many employees are expected to respond to work messages outside office hours. Laws should be introduced to give workers a legal ''right to disconnect''. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-031-individual-responsibility-vs-gov', 'Individual Responsibility vs Government Action for Climate', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Discuss Both Views & Opinion)', 'Some people believe that individual lifestyle changes (such as recycling and using public transit) are the key to reversing climate change. Others argue only government legislation and corporate regulation can make a meaningful difference. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-032-nuclear-energy-as-a-clean-altern', 'Nuclear Energy as a Clean Alternative', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Advantages vs Disadvantages)', 'To replace fossil fuels and combat global warming, several nations are constructing new nuclear power stations. Do the advantages of nuclear energy outweigh the potential environmental risks?', null, null, 250, 40),
  ('task2-033-single-use-plastics-total-ban', 'Single-Use Plastics Total Ban', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Agree / Disagree)', 'Plastic pollution in oceans and landfills has reached alarming levels. Governments should enforce an outright ban on all single-use plastic packaging and consumer products. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-034-protecting-endangered-species-vs', 'Protecting Endangered Species vs Human Needs', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Discuss Both Views & Opinion)', 'Some people argue that massive public funds should be spent saving endangered animal and plant species from extinction. Others argue human needs, such as healthcare and housing, must take absolute priority. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-035-deforestation-for-agricultural-e', 'Deforestation for Agricultural Expansion', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Causes & Solutions)', 'Vast areas of tropical rainforest are cleared every year to provide pasture for cattle and land for crops. What environmental problems does deforestation cause, and how can the international community halt this destruction while feeding growing populations?', null, null, 250, 40),
  ('task2-036-taxing-fossil-fuel-vehicles-subs', 'Taxing Fossil Fuel Vehicles & Subsidizing EVs', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Agree / Disagree)', 'Governments should levy heavy carbon taxes on petrol and diesel vehicles while subsidizing electric cars to accelerate green transport transition. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-037-throwaway-consumer-culture-waste', 'Throwaway Consumer Culture & Waste Management', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Causes & Solutions)', 'Modern consumer society encourages people to purchase cheap goods and discard them quickly, resulting in unprecedented waste mountains. What are the causes of this throwaway culture, and how can society transition to a circular economy?', null, null, 250, 40),
  ('task2-038-renewable-energy-transition-in-d', 'Renewable Energy Transition in Developing Economies', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Discuss Both Views & Opinion)', 'Some argue developing countries should be allowed to use cheap fossil fuels until their economies mature. Others maintain all countries must transition immediately to renewable wind and solar power regardless of economic status. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-039-global-water-scarcity-industrial', 'Global Water Scarcity & Industrial Depletion', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Problem & Solution)', 'Fresh drinking water shortages are becoming critical in many arid regions due to industrial overuse and changing climate patterns. What consequences will water scarcity have, and what global measures can be implemented to conserve freshwater resources?', null, null, 250, 40),
  ('task2-040-aviation-fuel-taxation-and-fligh', 'Aviation Fuel Taxation and Flight Limits', 'TASK_2_ESSAY', 'Environment, Climate & Energy (To What Extent)', 'Commercial air travel is one of the fastest-growing sources of greenhouse gas emissions. Some propose increasing airfare taxes drastically to discourage non-essential holiday flights. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-041-zoos-and-wild-animal-captivity', 'Zoos and Wild Animal Captivity', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Discuss Both Views & Opinion)', 'Some people believe keeping wild animals in zoos is cruel and obsolete in the 21st century. Others argue zoos play a vital role in biological research and species conservation. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-042-meat-consumption-and-global-envi', 'Meat Consumption and Global Environmental Footprint', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Agree / Disagree)', 'The industrial livestock industry generates more greenhouse gases than the entire global transportation sector. People should adopt a plant-based diet to protect the planet. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-043-urban-green-spaces-and-biodivers', 'Urban Green Spaces and Biodiversity Parks', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Advantages vs Disadvantages)', 'Many municipal councils are converting valuable commercial real estate in city centers into public parks, forests, and biodiversity reserves. Do the environmental and health advantages outweigh the economic costs?', null, null, 250, 40),
  ('task2-044-fast-fashion-impact-on-global-ec', 'Fast Fashion Impact on Global Ecosystems', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Causes & Solutions)', 'The rapid production of cheap, disposable fashion clothing causes tremendous water pollution, toxic chemical waste, and textile dumping. Why has fast fashion become so popular, and what actions can be taken to promote sustainable clothing?', null, null, 250, 40),
  ('task2-045-international-treaties-vs-nation', 'International Treaties vs National Economic Growth', 'TASK_2_ESSAY', 'Environment, Climate & Energy (Agree / Disagree)', 'Strict international environmental treaties limit the economic development of sovereign nations. Individual countries should be free to set their own environmental regulations. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-046-taxing-sugary-drinks-ultra-proce', 'Taxing Sugary Drinks & Ultra-Processed Foods', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Agree / Disagree)', 'Governments should introduce a high tax on fast food and sugar-sweetened beverages to discourage unhealthy eating and fund public healthcare. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-047-free-universal-healthcare-vs-pri', 'Free Universal Healthcare vs Private Insurance', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Discuss Both Views & Opinion)', 'Some argue comprehensive healthcare should be a fundamental human right fully funded by general taxation. Others believe private medical insurance provides higher quality care and reduces state debt. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-048-rising-obesity-rates-among-child', 'Rising Obesity Rates Among Children', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Causes & Solutions)', 'Obesity among children and teenagers has increased dramatically over the past three decades. What are the main drivers of this health epidemic, and what practical strategies can schools and families implement to reverse it?', null, null, 250, 40),
  ('task2-049-preventive-healthcare-vs-hospita', 'Preventive Healthcare vs Hospital Treatment Funding', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (To What Extent)', 'Governments spend the majority of their health budgets treating existing diseases in hospitals. It would be far more effective to invest heavily in public health campaigns promoting healthy diets and regular exercise. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-050-mental-health-awareness-public-i', 'Mental Health Awareness & Public Investment', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Discuss Both Views & Opinion)', 'In many countries, mental health disorders are now recognized as a leading cause of disability. Some believe mental health treatment deserves equal government funding to physical illness, while others prioritize physical emergency care. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-051-sedentary-lifestyles-and-office-', 'Sedentary Lifestyles and Office Ergonomics', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Causes & Solutions)', 'Modern desk-bound office jobs and digital entertainment have created an increasingly sedentary population, leading to chronic illness. What factors encourage this inactive lifestyle, and how can employers and communities foster physical activity?', null, null, 250, 40),
  ('task2-052-banning-tobacco-and-vaping-produ', 'Banning Tobacco and Vaping Products Completely', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Agree / Disagree)', 'Given the catastrophic health consequences and medical costs associated with smoking and vaping, all nicotine products should be made completely illegal. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-053-pharmaceutical-patent-monopolies', 'Pharmaceutical Patent Monopolies & Drug Pricing', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Discuss Both Views & Opinion)', 'Some argue pharmaceutical companies should hold exclusive patents on life-saving medicines to reward expensive research and development. Others believe essential medicines should be sold at affordable production cost worldwide. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-054-longevity-and-centenarian-aging-', 'Longevity and Centenarian Aging Populations', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Advantages vs Disadvantages)', 'Due to medical advancements, average life expectancy is exceeding 80 years in many countries. Do the advantages of an increasingly long-lived population outweigh the socio-economic disadvantages?', null, null, 250, 40),
  ('task2-055-alternative-holistic-medicine-vs', 'Alternative Holistic Medicine vs Scientific Medicine', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Discuss Both Views & Opinion)', 'Some individuals prefer relying on herbal, homeopathic, or holistic remedies for health issues. Others argue only scientifically validated modern medicine should be practiced and licensed. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-056-compulsory-childhood-vaccination', 'Compulsory Childhood Vaccinations', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Agree / Disagree)', 'Governments should mandate that all children receive standard routine immunizations before being admitted to public schools. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-057-advertising-fast-food-to-childre', 'Advertising Fast Food to Children', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Agree / Disagree)', 'Television and internet commercials advertising junk food and sugary snacks aimed at children should be completely banned by law. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-058-personal-responsibility-for-illn', 'Personal Responsibility for Illness & Healthcare Charges', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Discuss Both Views & Opinion)', 'Some propose that individuals who smoke, drink heavily, or neglect their fitness should pay higher taxes or direct medical fees for treatment. Others argue state healthcare must treat all citizens without moral discrimination. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-059-stress-and-burnout-in-high-incom', 'Stress and Burnout in High-Income Societies', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Causes & Solutions)', 'Despite high material standards of living, people in developed countries report rising rates of psychological stress and workplace burnout. What factors cause this paradox, and what lifestyle or structural adjustments can relieve it?', null, null, 250, 40),
  ('task2-060-genetically-modified-foods-gmos-', 'Genetically Modified Foods (GMOs) and Global Hunger', 'TASK_2_ESSAY', 'Health, Diet & Public Healthcare (Advantages vs Disadvantages)', 'Genetically modified crops can withstand droughts and pests, potentially ending global food shortages. Do the agricultural benefits of genetically engineered food outweigh potential health and ecological risks?', null, null, 250, 40),
  ('task2-061-elderly-care-family-homes-vs-pro', 'Elderly Care: Family Homes vs Professional Care Centers', 'TASK_2_ESSAY', 'Society, Family & Demographics (Discuss Both Views & Opinion)', 'Some believe adult children have a moral obligation to care for aging parents in their own homes. Others argue specialized retirement homes and professional geriatric facilities offer superior medical and social care. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-062-decline-in-birth-rates-in-develo', 'Decline in Birth Rates in Developed Nations', 'TASK_2_ESSAY', 'Society, Family & Demographics (Causes & Consequences)', 'Many industrialized countries are experiencing historically low birth rates, leading to shrinking and aging populations. What are the causes of this demographic decline, and what consequences will it have for society and the economy?', null, null, 250, 40),
  ('task2-063-nuclear-families-vs-extended-mul', 'Nuclear Families vs Extended Multi-Generational Living', 'TASK_2_ESSAY', 'Society, Family & Demographics (Advantages vs Disadvantages)', 'In many modern cultures, multi-generational households have been replaced by small nuclear family units living independently. Do the advantages of this living arrangement outweigh the disadvantages?', null, null, 250, 40),
  ('task2-064-parenthood-delay-for-career-esta', 'Parenthood Delay for Career Establishment', 'TASK_2_ESSAY', 'Society, Family & Demographics (Advantages vs Disadvantages)', 'Young adults are increasingly postponing marriage and having children until their thirties or forties to establish professional careers. Do the benefits of delayed parenthood outweigh the drawbacks?', null, null, 250, 40),
  ('task2-065-equal-parental-leave-for-fathers', 'Equal Parental Leave for Fathers and Mothers', 'TASK_2_ESSAY', 'Society, Family & Demographics (Agree / Disagree)', 'Employers should offer identical paid parental leave durations to both fathers and mothers following the birth or adoption of a child. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-066-wealth-disparity-income-inequali', 'Wealth Disparity & Income Inequality', 'TASK_2_ESSAY', 'Society, Family & Demographics (Problem & Solution)', 'The gap between the richest individuals and the poorest members of society continues to widen in both developed and emerging nations. What societal problems arise from extreme income inequality, and what fiscal policies can narrow this divide?', null, null, 250, 40),
  ('task2-067-living-alone-as-a-single-person-', 'Living Alone as a Single-Person Household', 'TASK_2_ESSAY', 'Society, Family & Demographics (Advantages vs Disadvantages)', 'In large metropolitan cities, a record proportion of adults now live alone in single-person apartments. Do the advantages of living alone outweigh the social and emotional disadvantages?', null, null, 250, 40),
  ('task2-068-loss-of-community-spirit-in-urba', 'Loss of Community Spirit in Urban Neighborhoods', 'TASK_2_ESSAY', 'Society, Family & Demographics (Causes & Solutions)', 'People in modern urban apartment complexes often do not know their neighbors, resulting in a breakdown of neighborhood community bonds. Why is this occurring, and how can local councils recreate a sense of community solidarity?', null, null, 250, 40),
  ('task2-069-universal-basic-income-ubi', 'Universal Basic Income (UBI)', 'TASK_2_ESSAY', 'Society, Family & Demographics (Advantages vs Disadvantages)', 'Some economists advocate that governments should pay every adult citizen a regular guaranteed Universal Basic Income regardless of employment status. Do the advantages of UBI outweigh the financial risks?', null, null, 250, 40),
  ('task2-070-mandatory-community-service-for-', 'Mandatory Community Service for School Leavers', 'TASK_2_ESSAY', 'Society, Family & Demographics (To What Extent)', 'Young people should be required to complete one year of unpaid community or civic service upon finishing high school to cultivate social responsibility. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-071-youth-unemployment-and-graduate-', 'Youth Unemployment and Graduate Underemployment', 'TASK_2_ESSAY', 'Society, Family & Demographics (Causes & Solutions)', 'In many countries, a large proportion of young university graduates struggle to find jobs matching their qualifications. What are the roots of graduate unemployment, and how can universities and governments bridge this mismatch?', null, null, 250, 40),
  ('task2-072-impact-of-advertising-on-materia', 'Impact of Advertising on Materialism in Children', 'TASK_2_ESSAY', 'Society, Family & Demographics (Agree / Disagree)', 'Aggressive marketing aimed at young audiences has created a hyper-materialistic culture where children equate happiness with owning luxury consumer possessions. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-073-role-models-celebrities-vs-paren', 'Role Models: Celebrities vs Parents and Teachers', 'TASK_2_ESSAY', 'Society, Family & Demographics (Discuss Both Views & Opinion)', 'Some argue movie stars, musicians, and sports celebrities have the greatest influence over teenage behavior and values. Others believe parents and educators remain the primary role models. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-074-tradition-vs-modernity-in-social', 'Tradition vs Modernity in Social Customs', 'TASK_2_ESSAY', 'Society, Family & Demographics (Discuss Both Views & Opinion)', 'Some believe adhering strictly to traditional social customs and cultural etiquette preserves national identity. Others argue society must modernize and abandon outdated cultural practices. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-075-gender-quotas-on-corporate-board', 'Gender Quotas on Corporate Boards', 'TASK_2_ESSAY', 'Society, Family & Demographics (Agree / Disagree)', 'Governments should enforce legal quotas requiring commercial corporations to appoint women to at least 40% of executive board positions. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-076-remote-working-vs-in-office-coll', 'Remote Working vs In-Office Collaboration', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Discuss Both Views & Opinion)', 'Some employees believe working remotely from home full-time yields superior productivity and work-life balance. Others maintain daily office attendance is indispensable for team creativity and corporate culture. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-077-four-day-work-week-without-pay-c', 'Four-Day Work Week Without Pay Cuts', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Advantages vs Disadvantages)', 'Several companies and governments are trialing a four-day work week (32 hours) with no reduction in employee pay. Do the advantages of a four-day work week outweigh the disadvantages?', null, null, 250, 40),
  ('task2-078-job-satisfaction-vs-high-salary-', 'Job Satisfaction vs High Salary Priority', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Discuss Both Views & Opinion)', 'When choosing a career, some people prioritize personal passion, fulfillment, and job satisfaction. Others believe earning a high salary is the only logical criteria in modern society. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-079-the-gig-economy-freelance-instab', 'The Gig Economy & Freelance Instability', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Advantages vs Disadvantages)', 'Millions of people now work in the ''gig economy'' as freelance delivery riders, drivers, and contract designers rather than permanent staff. Do the flexible advantages of gig employment outweigh the lack of social benefits and job security?', null, null, 250, 40),
  ('task2-080-retirement-age-fixed-threshold-v', 'Retirement Age: Fixed Threshold vs Working Indefinitely', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Discuss Both Views & Opinion)', 'Some argue senior citizens should retire compulsorily at 65 to make room for younger jobseekers. Others believe people should be allowed to work as long as they remain competent and willing. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-081-lifelong-single-career-vs-multip', 'Lifelong Single-Career vs Multiple Career Pivots', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Advantages vs Disadvantages)', 'In past generations, employees stayed with a single employer or career track for their entire lives. Today, workers switch careers and industries multiple times. Do the advantages of frequent career changes outweigh the disadvantages?', null, null, 250, 40),
  ('task2-082-outsourcing-manufacturing-to-dev', 'Outsourcing Manufacturing to Developing Nations', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Advantages vs Disadvantages)', 'Multinational corporations regularly outsource factories and customer service jobs to developing countries with cheaper labor costs. Do the global benefits of outsourcing outweigh the domestic drawbacks?', null, null, 250, 40),
  ('task2-083-automation-of-blue-collar-vs-whi', 'Automation of Blue-Collar vs White-Collar Jobs', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Two-Part Question)', 'Historically, machines automated manual factory labor; today, algorithms and software automate intellectual white-collar professions. How will this trend affect workforce structures, and how can educational institutions prepare future graduates?', null, null, 250, 40),
  ('task2-084-executive-salaries-vs-regular-wo', 'Executive Salaries vs Regular Worker Wages', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Agree / Disagree)', 'Corporate chief executive officers (CEOs) frequently earn hundreds of times more than average employees in the same company. Governments should place a legal ceiling on executive compensation. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-085-unpaid-internships-for-universit', 'Unpaid Internships for University Students', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Agree / Disagree)', 'Companies frequently hire university students as unpaid interns in exchange for work experience and professional references. Unpaid internships exploit young workers and should be banned. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-086-globalization-and-the-homogeniza', 'Globalization and the Homogenization of Local Markets', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Discuss Both Views & Opinion)', 'Some argue global trade brings cheaper consumer goods and technological modernization to all regions. Others argue it wipes out local independent retailers and traditional cottage industries. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-087-vocational-trades-vs-academic-de', 'Vocational Trades vs Academic Degrees', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Agree / Disagree)', 'Society places too much prestige on university degrees and undervalues manual skilled trades like plumbing, carpentry, and electrical work. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-088-working-long-overtime-hours-and-', 'Working Long Overtime Hours and Productivity', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Causes & Solutions)', 'In competitive economies, employees often work 50 to 60 hours per week despite evidence that long hours harm health and reduce productivity. Why does this culture persist, and how can companies promote balanced work schedules?', null, null, 250, 40),
  ('task2-089-entrepreneurship-training-in-hig', 'Entrepreneurship Training in High Schools', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (To What Extent)', 'Instead of preparing students solely to be employees, high schools should actively teach entrepreneurship, business creation, and investment. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-090-tourism-as-a-driver-of-regional-', 'Tourism as a Driver of Regional Economic Growth', 'TASK_2_ESSAY', 'Work, Career & The Global Economy (Advantages vs Disadvantages)', 'Many developing regions rely almost entirely on international tourism revenue to fuel their economies. Do the economic advantages of tourism dependency outweigh the environmental and cultural vulnerabilities?', null, null, 250, 40),
  ('task2-091-prison-rehabilitation-vs-retribu', 'Prison Rehabilitation vs Retributive Punishment', 'TASK_2_ESSAY', 'Crime, Law & Justice (Discuss Both Views & Opinion)', 'Some people believe the fundamental purpose of prison is to punish criminals for wrongdoing. Others argue correctional institutions should focus strictly on education, vocational training, and rehabilitation. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-092-capital-punishment-the-death-pen', 'Capital Punishment / The Death Penalty', 'TASK_2_ESSAY', 'Crime, Law & Justice (Agree / Disagree)', 'Capital punishment is necessary to deter heinous crimes and provide ultimate justice for victims'' families. To what extent do you agree or disagree with the death penalty?', null, null, 250, 40),
  ('task2-093-juvenile-delinquency-and-youth-o', 'Juvenile Delinquency and Youth Offender Sentencing', 'TASK_2_ESSAY', 'Crime, Law & Justice (Discuss Both Views & Opinion)', 'Some argue teenagers under 18 who commit serious violent offenses should be tried and sentenced as adult criminals. Others believe juvenile offenders should receive community reform rather than adult prison sentences. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-094-white-collar-corporate-crime-vs-', 'White-Collar Corporate Crime vs Street Theft', 'TASK_2_ESSAY', 'Crime, Law & Justice (Agree / Disagree)', 'Financial corporate fraud, embezzlement, and insider trading inflict far greater financial and societal damage than burglary or petty theft, and should carry harsher prison sentences. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-095-causes-of-recidivism-repeat-offe', 'Causes of Recidivism & Repeat Offending', 'TASK_2_ESSAY', 'Crime, Law & Justice (Causes & Solutions)', 'A high percentage of released convicts commit new offenses and return to prison within two years. What are the primary factors causing recidivism, and what rehabilitation measures can reintegrate ex-offenders into society?', null, null, 250, 40),
  ('task2-096-community-service-for-minor-non-', 'Community Service for Minor Non-Violent Offenses', 'TASK_2_ESSAY', 'Crime, Law & Justice (Advantages vs Disadvantages)', 'Instead of short prison sentences, some legal systems sentence minor non-violent offenders to mandatory unpaid community service. Do the advantages of community service sentences outweigh the disadvantages?', null, null, 250, 40),
  ('task2-097-gun-control-legislation-and-civi', 'Gun Control Legislation and Civilian Firearms', 'TASK_2_ESSAY', 'Crime, Law & Justice (Discuss Both Views & Opinion)', 'Some believe private citizens should possess a legal right to own firearms for self-defense. Others argue that strict bans on civilian firearms drastically reduce homicide rates and mass shootings. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-098-poverty-and-crime-rates-correlat', 'Poverty and Crime Rates Correlation', 'TASK_2_ESSAY', 'Crime, Law & Justice (Discuss Both Views & Opinion)', 'Some criminologists state that poverty, lack of educational opportunities, and social deprivation are the sole causes of crime. Others believe criminal actions stem from individual moral deficiency and personal greed. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-099-mandatory-minimum-sentences-for-', 'Mandatory Minimum Sentences for Drug Possession', 'TASK_2_ESSAY', 'Crime, Law & Justice (Advantages vs Disadvantages)', 'Some countries impose strict mandatory minimum prison sentences on anyone caught in possession of illegal narcotics. Do the deterrent benefits of strict drug sentencing outweigh the socio-economic costs of mass incarceration?', null, null, 250, 40),
  ('task2-100-public-media-reporting-on-violen', 'Public Media Reporting on Violent Crimes', 'TASK_2_ESSAY', 'Crime, Law & Justice (Discuss Both Views & Opinion)', 'Some people believe news media should report graphic details of violent crime to keep citizens vigilant. Others argue sensational crime reporting creates irrational panic and inspires copycat offenses. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-101-electronic-ankle-tagging-vs-inca', 'Electronic Ankle Tagging vs Incarceration', 'TASK_2_ESSAY', 'Crime, Law & Justice (Advantages vs Disadvantages)', 'Advances in GPS electronic tagging allow judges to place offenders under home house arrest rather than sending them to prison. Do the cost and social benefits of electronic monitoring outweigh the security risks?', null, null, 250, 40),
  ('task2-102-victim-offender-restorative-just', 'Victim-Offender Restorative Justice Programs', 'TASK_2_ESSAY', 'Crime, Law & Justice (To What Extent)', 'Restorative justice programs bring victims face-to-face with offenders to discuss the emotional and physical impact of the crime. To what extent do you think restorative justice is effective compared to traditional courtroom sentencing?', null, null, 250, 40),
  ('task2-103-police-body-cameras-and-accounta', 'Police Body Cameras and Accountability', 'TASK_2_ESSAY', 'Crime, Law & Justice (Advantages vs Disadvantages)', 'Police departments around the world now require patrol officers to wear active body cameras during all citizen interactions. Do the advantages of police body cameras outweigh the potential privacy and operational challenges?', null, null, 250, 40),
  ('task2-104-cybercrime-ransomware-and-intern', 'Cybercrime, Ransomware and International Law', 'TASK_2_ESSAY', 'Crime, Law & Justice (Problem & Solution)', 'Cybercrime, online financial fraud, and international ransomware attacks on infrastructure are escalating exponentially. Why is it difficult to prosecute cybercriminals, and what global treaties are needed to enforce justice across borders?', null, null, 250, 40),
  ('task2-105-parental-liability-for-juvenile-', 'Parental Liability for Juvenile Offenses', 'TASK_2_ESSAY', 'Crime, Law & Justice (Agree / Disagree)', 'Parents should be held legally and financially responsible for property damage and vandalism committed by their children under 16 years of age. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-106-arts-and-culture-funding-vs-heal', 'Arts and Culture Funding vs Healthcare and Infrastructure', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Discuss Both Views & Opinion)', 'Some people argue governments should invest taxpayer revenue primarily in critical services like hospitals, public transport, and schools. Others believe allocating funds to art galleries, opera houses, and museums is equally essential for national identity. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-107-public-transit-subsidies-and-fre', 'Public Transit Subsidies and Free Commuting', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Advantages vs Disadvantages)', 'Several cities have made municipal bus, metro, and tram networks completely free to all passengers, funded through local taxes. Do the environmental and traffic benefits of free public transit outweigh the fiscal costs?', null, null, 250, 40),
  ('task2-108-foreign-aid-to-developing-nation', 'Foreign Aid to Developing Nations vs Domestic Spending', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Discuss Both Views & Opinion)', 'Some citizens believe wealthy industrialized countries have a humanitarian duty to send financial aid and medical relief to poorer countries. Others believe all government tax revenues should be spent solving domestic social problems first. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-109-public-parks-vs-affordable-housi', 'Public Parks vs Affordable Housing Construction', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Discuss Both Views & Opinion)', 'With metropolitan housing shortages, some argue public land in cities should be utilized to build affordable residential housing. Others believe urban parks, green spaces, and botanical gardens must be preserved at all costs. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-110-progressive-income-taxation-on-h', 'Progressive Income Taxation on High Earners', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Agree / Disagree)', 'To create a fairer society and fund welfare services, the wealthiest citizens should be taxed at rates up to 50% or higher. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-111-hosting-mega-sporting-events-oly', 'Hosting Mega Sporting Events (Olympics / World Cup)', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Advantages vs Disadvantages)', 'Hosting international sporting spectacles like the Olympic Games or FIFA World Cup requires billions in infrastructure spending. Do the tourism and prestige advantages of hosting mega-events outweigh the immense financial costs?', null, null, 250, 40),
  ('task2-112-national-defense-budgets-vs-soci', 'National Defense Budgets vs Social Welfare Spending', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (To What Extent)', 'Governments spend staggering portions of their national budgets on military arms, fighter jets, and defense. Some argue this money should be redirected towards eradicating poverty and funding public hospitals. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-113-state-funding-for-scientific-res', 'State Funding for Scientific Research vs Private Investment', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Discuss Both Views & Opinion)', 'Some believe fundamental scientific and space research should be funded by government grants because it serves the public good. Others think commercial corporations should finance scientific innovation. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-114-preservation-of-historic-heritag', 'Preservation of Historic Heritage Buildings', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Advantages vs Disadvantages)', 'Governments spend considerable tax funds maintaining historic castles, palaces, and ancient monuments. Do the cultural and tourist advantages of historic building preservation outweigh the costs of upkeep?', null, null, 250, 40),
  ('task2-115-state-censorship-of-the-internet', 'State Censorship of the Internet and Public Media', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Agree / Disagree)', 'Governments have a moral obligation to censor offensive, extremist, or misleading material on the internet to protect vulnerable citizens. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-116-congestion-charging-in-city-cent', 'Congestion Charging in City Centers', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Advantages vs Disadvantages)', 'To combat traffic jams, many major cities charge drivers a daily toll to enter the central commercial zone. Do the advantages of urban congestion pricing outweigh the disadvantages for commuters?', null, null, 250, 40),
  ('task2-117-mandatory-voting-laws-in-democra', 'Mandatory Voting Laws in Democratic Elections', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Agree / Disagree)', 'In some countries, voting in general parliamentary elections is compulsory by law, with fines issued to non-voters. Should democratic voting be mandatory for all adult citizens? Give reasons for your answer.', null, null, 250, 40),
  ('task2-118-subsidizing-farmers-and-agricult', 'Subsidizing Farmers and Agricultural Products', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Advantages vs Disadvantages)', 'Many governments pay heavy annual subsidies to domestic farmers to keep food prices low and maintain food security. Do the economic advantages of farm subsidies outweigh the market distortions they create?', null, null, 250, 40),
  ('task2-119-government-incentives-for-green-', 'Government Incentives for Green Renewable Technology', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (To What Extent)', 'Governments should offer substantial tax reductions and grants to families who install solar panels and heat pumps in their homes. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-120-infrastructure-spending-in-rural', 'Infrastructure Spending in Rural vs Metropolitan Areas', 'TASK_2_ESSAY', 'Government, Public Spending & Policy (Discuss Both Views & Opinion)', 'Some argue government transport and digital infrastructure spending should prioritize large metropolises where the majority of citizens live. Others argue rural and remote regions need higher per-capita investment to prevent economic depopulation. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-121-impact-of-advertising-on-consume', 'Impact of Advertising on Consumer Behavior', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Discuss Both Views & Opinion)', 'Some believe commercial advertising provides useful information about new products and fuels economic vitality. Others argue advertising manipulates consumer psychology and creates false artificial needs. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-122-the-dominance-of-english-as-a-gl', 'The Dominance of English as a Global Lingua Franca', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Advantages vs Disadvantages)', 'English has become the dominant global language for international commerce, science, and the internet. Do the advantages of having one universal global language outweigh the risk of minor indigenous languages becoming extinct?', null, null, 250, 40),
  ('task2-123-celebrity-privacy-vs-public-medi', 'Celebrity Privacy vs Public Media Scrutiny', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Discuss Both Views & Opinion)', 'Some argue famous actors, sports stars, and political figures earn exorbitant incomes and must accept intrusive media coverage of their private lives. Others believe everyone possesses a fundamental right to privacy. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-124-preservation-of-traditional-musi', 'Preservation of Traditional Music and Folk Art', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Causes & Solutions)', 'Traditional indigenous music, folklore, and dance are being replaced by globalized American and western pop culture. Why is traditional folklore declining, and what measures can cultural bodies implement to keep local traditions vibrant?', null, null, 250, 40),
  ('task2-125-museum-entry-fees-vs-free-public', 'Museum Entry Fees vs Free Public Admission', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Discuss Both Views & Opinion)', 'Some argue national museums and art galleries should charge entry fees to cover operational and maintenance costs. Others maintain public museums must be completely free of charge to promote education and culture. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-126-fake-news-and-social-media-infor', 'Fake News and Social Media Information Literacy', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Causes & Solutions)', 'The rapid spread of unverified information and deliberate ''fake news'' on digital networks undermines democratic elections and public health. What factors enable misinformation to spread so rapidly, and how can society cultivate critical media literacy?', null, null, 250, 40),
  ('task2-127-banning-advertising-of-luxury-go', 'Banning Advertising of Luxury Goods', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Agree / Disagree)', 'Advertising expensive luxury items like high-end watches, luxury cars, and designer clothing creates social envy and unrealistic expectations. Some propose banning luxury marketing. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-128-reading-fiction-novels-vs-practi', 'Reading Fiction Novels vs Practical Non-Fiction', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Discuss Both Views & Opinion)', 'Some people believe reading literary fiction is a waste of time and that people should read factual non-fiction books to gain real knowledge. Others believe reading stories develops empathy, imagination, and language eloquence. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-129-preserving-minority-languages-fr', 'Preserving Minority Languages from Extinction', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (To What Extent)', 'Every month, several indigenous minority languages disappear forever. Some believe spending money to document and revive dying languages is pointless when a few global languages dominate. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-130-digital-streaming-platforms-and-', 'Digital Streaming Platforms and Traditional Cinema', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Advantages vs Disadvantages)', 'The proliferation of home streaming services (such as Netflix and Disney+) has led to declining attendance in public movie theaters. Do the advantages of home digital streaming outweigh the decline of community cinema culture?', null, null, 250, 40),
  ('task2-131-sponsorship-of-arts-by-private-c', 'Sponsorship of Arts by Private Corporations', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Advantages vs Disadvantages)', 'Many modern artists, theater productions, and art exhibitions rely on commercial sponsorship from banks and corporations rather than government funding. Do the advantages of private corporate arts sponsorship outweigh the disadvantages?', null, null, 250, 40),
  ('task2-132-children-imitating-influencer-li', 'Children Imitating Influencer Lifestyles on Social Media', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Problems & Solutions)', 'Young adolescents increasingly aspire to become online influencers rather than pursuing traditional professions like medicine, engineering, or teaching. What societal problems could this mindset cause, and how should educational institutions respond?', null, null, 250, 40),
  ('task2-133-public-art-and-graffiti-vandalis', 'Public Art and Graffiti: Vandalism or Creative Expression?', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Discuss Both Views & Opinion)', 'Some believe unauthorized street art and graffiti is criminal vandalism that degrades neighborhoods and should be strictly penalized. Others consider street murals a valuable form of democratic cultural expression. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-134-international-sporting-competiti', 'International Sporting Competition as a Peace Promoter', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (To What Extent)', 'International sporting tournaments like the Olympics foster goodwill and mutual understanding between rival nations. To what extent do you agree or disagree that international sport reduces geopolitical conflict?', null, null, 250, 40),
  ('task2-135-censoring-violent-lyrics-and-exp', 'Censoring Violent Lyrics and Explicit Music', 'TASK_2_ESSAY', 'Arts, Culture, Media & Advertising (Agree / Disagree)', 'Songs that contain sexually explicit or violent lyrics should be banned from public radio stations and music streaming charts. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-136-banning-private-cars-from-centra', 'Banning Private Cars from Central Metropolitan Areas', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Agree / Disagree)', 'To eradicate gridlock traffic and hazardous smog, municipal authorities should ban all private cars from driving within inner city centers, permitting only public buses, cycles, and pedestrians. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-137-overtourism-and-damage-to-histor', 'Overtourism and Damage to Historic Heritage Sites', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Causes & Solutions)', 'Popular tourist destinations like Venice, Kyoto, and Machu Picchu suffer from severe overcrowding, rising living costs for locals, and degradation of historical monuments. What causes overtourism, and what sustainable tourism policies should be enforced?', null, null, 250, 40),
  ('task2-138-high-speed-rail-networks-vs-dome', 'High-Speed Rail Networks vs Domestic Air Travel', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Advantages vs Disadvantages)', 'Many countries are investing heavily in high-speed bullet train networks to replace short-haul domestic flights. Do the environmental and connectivity advantages of high-speed rail outweigh the immense engineering costs?', null, null, 250, 40),
  ('task2-139-rural-to-urban-migration-and-meg', 'Rural-to-Urban Migration and Mega-City Growth', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Causes & Consequences)', 'Millions of people in developing countries migrate from agrarian villages to congested mega-cities every year. What are the main drivers of rural-to-urban migration, and what consequences does this migration produce for both cities and rural communities?', null, null, 250, 40),
  ('task2-140-living-in-modern-high-rise-apart', 'Living in Modern High-Rise Apartments vs Suburban Houses', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Discuss Both Views & Opinion)', 'Some believe living in high-rise city apartments is the most efficient, sustainable way to house urban populations. Others argue detached houses with private gardens in quiet suburban areas offer vastly superior quality of life. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-141-e-scooters-and-bicycle-lanes-in-', 'E-Scooters and Bicycle Lanes in Modern Cities', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Advantages vs Disadvantages)', 'Many cities are replacing car lanes with dedicated paths for bicycles and electric scooters to promote green micro-mobility. Do the advantages of e-scooters and cycling lanes outweigh the safety hazards and traffic disruption?', null, null, 250, 40),
  ('task2-142-cultural-homogenization-and-glob', 'Cultural Homogenization and Global Brand Dominance', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Agree / Disagree)', 'Due to globalization, city shopping centers around the world look virtually identical, filled with the same international retail and fast food brands. This destroys authentic cultural uniqueness. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-143-subsidizing-rural-relocation-to-', 'Subsidizing Rural Relocation to Decongest Megacities', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (To What Extent)', 'Governments should offer monetary subsidies and tax holidays to businesses and families willing to move out of overcrowded capitals into declining provincial towns. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-144-ecotourism-and-remote-environmen', 'Ecotourism and Remote Environmental Exploration', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Advantages vs Disadvantages)', 'Ecotourism promises to support conservation by allowing tourists to visit fragile rainforests, glaciers, and coral reefs. Do the economic and educational advantages of ecotourism outweigh the environmental damage caused by travel?', null, null, 250, 40),
  ('task2-145-public-transport-vs-expanding-hi', 'Public Transport vs Expanding Highway Networks', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Discuss Both Views & Opinion)', 'When tackling highway congestion, some argue governments should expand multi-lane motorways to increase vehicle capacity. Others argue building wider roads induces more traffic, and funds must be spent solely on trains and subways. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-146-the-15-minute-city-urban-plannin', 'The 15-Minute City Urban Planning Model', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Advantages vs Disadvantages)', 'The ''15-minute city'' urban planning concept proposes that all essential daily amenities (groceries, schools, clinics, parks, work) should be accessible within a 15-minute walk or bike ride from every home. Do the advantages of this urban model outweigh its practical challenges?', null, null, 250, 40),
  ('task2-147-international-tourism-and-cultur', 'International Tourism and Cultural Misunderstandings', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Discuss Both Views & Opinion)', 'Some believe international tourism breaks down cultural prejudices and builds international harmony. Others argue mass tourism leads to shallow consumerism, commercialization of sacred customs, and resentment among locals. Discuss both views and give your opinion.', null, null, 250, 40),
  ('task2-148-gentrification-of-historic-worki', 'Gentrification of Historic Working-Class Neighborhoods', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Advantages vs Disadvantages)', 'In many cities, neglected working-class neighborhoods are renovated with upscale cafes and luxury developments (''gentrification''). Do the economic advantages of gentrification outweigh the displacement of long-term low-income residents?', null, null, 250, 40),
  ('task2-149-space-tourism-for-ultra-wealthy-', 'Space Tourism for Ultra-Wealthy Travelers', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Agree / Disagree)', 'Private aerospace firms now offer commercial sub-orbital spaceflights to wealthy tourists. Some argue space tourism causes immense carbon pollution for frivolous vanity and should be heavily taxed or prohibited. To what extent do you agree or disagree?', null, null, 250, 40),
  ('task2-150-air-quality-in-asian-and-global-', 'Air Quality in Asian and Global Megacities', 'TASK_2_ESSAY', 'Cities, Transport & Globalization (Causes & Solutions)', 'Air pollution in many global megacities frequently exceeds safe World Health Organization limits, creating severe public health crises. What are the key drivers of urban toxic smog, and what structural initiatives can restore clean air to modern metropolises?', null, null, 250, 40),
  ('task1-acad-water-consumption', 'Global Water Usage (1900–2000)', 'TASK_1_ACADEMIC', 'Line Graph & Data Trends', 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'The line graph below illustrates global water consumption in three distinct sectors (Agriculture, Industrial, and Domestic) from 1900 to 2000 in cubic kilometers per year.', 'LINE_GRAPH', 150, 20),
  ('task1-acad-electricity-production', 'Electricity Production by Source', 'TASK_1_ACADEMIC', 'Bar Chart & Country Comparison', 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'The bar chart compares the percentage of electricity generated from fossil fuels, nuclear power, and renewable resources across four European nations (Germany, France, UK, and Sweden) in 2020.', 'BAR_CHART', 150, 20),
  ('task1-acad-household-expenditure', 'Household Spending Patterns (1980 vs 2020)', 'TASK_1_ACADEMIC', 'Pie Charts & Budget Proportions', 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'The two pie charts compare the proportion of average family income spent on five essential budget categories (Food, Housing, Transport, Energy, and Recreation) in 1980 and 2020.', 'PIE_CHARTS', 150, 20),
  ('task1-acad-brick-manufacturing', 'Industrial Brick Manufacturing Process', 'TASK_1_ACADEMIC', 'Process Diagram & Linear Flowchart', 'Summarise the information by selecting and reporting the main features, and describe the stages of the process where relevant.', 'The flowchart below illustrates the sequential industrial stages involved in manufacturing construction bricks from raw clay excavation to market delivery.', 'PROCESS_DIAGRAM', 150, 20),
  ('task1-acad-hydroelectric-dam', 'Hydroelectric Power Station Generation Cycle', 'TASK_1_ACADEMIC', 'Process Diagram & Engineering Flow', 'Summarise the information by selecting and reporting the main features, and describe the stages of the energy generation cycle where relevant.', 'The diagram shows the operational mechanism and sequential cycle by which a hydroelectric dam harnesses water pressure to generate and transmit electrical power to the national grid.', 'PROCESS_DIAGRAM', 150, 20),
  ('task1-acad-norbiton-town-map', 'Town of Norbiton Redevelopment Plan', 'TASK_1_ACADEMIC', 'Map Comparison (Existing vs Proposed Plan)', 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'The two maps show the industrial town of Norbiton as it is currently situated, and the planned municipal redevelopment proposal for the future.', 'MAP_COMPARISON', 150, 20),
  ('task1-acad-felixstone-coastal-resort', 'Coastal Village of Felixstone (1995 vs 2025)', 'TASK_1_ACADEMIC', 'Map Comparison (Historical vs Modern Resort)', 'Summarise the information by selecting and reporting the main features, and make comparisons between the two time periods.', 'The two maps illustrate the transformation of the coastal village of Felixstone from a traditional fishing settlement in 1995 into a modern recreational tourist resort in 2025.', 'MAP_COMPARISON', 150, 20),
  ('task1-acad-tourist-destinations-table', 'International Tourist Arrivals & Revenue', 'TASK_1_ACADEMIC', 'Statistical Matrix & Data Table', 'Summarise the information by selecting and reporting the main features, and make comparisons where relevant.', 'The table shows the number of international visitor arrivals (millions) and tourism revenue (billion USD) in five leading countries in 2015 and 2023.', 'TABLE', 150, 20),
  ('task1-gen-accommodation-complaint', 'Letter to Rental Agency', 'TASK_1_GENERAL', 'Formal Complaint Letter', 'You recently rented an apartment through a housing agency, but you have experienced several maintenance issues that have not been fixed despite your initial requests.
